using IdentityContext=Shop.Modules.Identity.IdentityDbContext;
namespace Shop.SqlTests;
public sealed class CreditUpfrontSqlTests():CreditRequirementsSqlBase(new SqlFixture()),IAsyncLifetime
{
    private WebApplicationFactory<Program>? auth;private Task<HttpClient> Staff(string role)=>base.Staff(role,auth??=sql.Factory.WithWebHostBuilder(_=>{}));public Task InitializeAsync()=>sql.InitializeAsync();public async Task DisposeAsync(){auth?.Dispose();await sql.DisposeAsync();}
    private sealed record Scenario(HttpClient Customer,string Owner,JsonNode Order,JsonNode Schedule,string Variant);
    private static string V(JsonNode n,string k)=>CreditCheckoutQuoteQa.Text(n,k);private static string OrderId(Scenario s)=>V(s.Order["summary"]!,"id");private static string Base(Scenario s)=>"/api/admin/credit/orders/"+s.Owner+"/"+OrderId(s)+"/upfront";private static string Own(Scenario s)=>"/api/credit/orders/"+OrderId(s)+"/upfront";private static string Schedule(Scenario s)=>"/api/admin/credit/orders/"+s.Owner+"/"+OrderId(s)+"/schedule";
    private static async Task<JsonNode> ReadUpfront(HttpResponseMessage response){using(response){var raw=await response.Content.ReadAsStringAsync();Assert.True(response.IsSuccessStatusCode,$"HTTP{(int)response.StatusCode}: {raw}");Assert.Contains("no-store",response.Headers.CacheControl!.ToString());Assert.Contains("noindex",response.Headers.GetValues("X-Robots-Tag").Single());if(Environment.GetEnvironmentVariable("SHOP_CREDIT_UPFRONT_WIRE_DIR")is{Length:>0}dir&&response.RequestMessage!.RequestUri!.AbsolutePath.Contains("/upfront",StringComparison.Ordinal)){Directory.CreateDirectory(dir);var id=Id();await File.WriteAllTextAsync(Path.Combine(dir,id+".json"),raw);await File.WriteAllTextAsync(Path.Combine(dir,id+".meta.json"),JsonSerializer.Serialize(new{actualSqlHttpResponse=true,syntheticQaOnly=true,status=(int)response.StatusCode,method=response.RequestMessage.Method.Method,path=response.RequestMessage.RequestUri.PathAndQuery}));}return JsonNode.Parse(raw)!;}}
    private async Task<Scenario> Ready(HttpClient finance,HttpClient reviewer,bool zero=false)
    {
        using var helper=new CreditOrderSqlTests(sql);var s=await helper.Ready(finance,reviewer);
        if(zero){s.Customer.Dispose();await using var edit=sql.Factory.Services.CreateAsyncScope();var catalog=edit.ServiceProvider.GetRequiredService<CatalogDbContext>();var product=await catalog.Products.SingleAsync(p=>p.Variants.Any(v=>v.Id==s.Goods.Variant));product.IsDigital=true;await catalog.SaveChangesAsync();var credit=edit.ServiceProvider.GetRequiredService<CreditDbContext>();var plan=await credit.Plans.SingleAsync(p=>p.Id==s.Goods.Plan.Id);plan.DownPaymentBasisPoints=0;await credit.SaveChangesAsync();var goods=s.Goods with{Plan=s.Goods.Plan with{Version=Convert.ToBase64String(plan.Version),DownPaymentBasisPoints=0}};s=await helper.Ready(finance,reviewer,goods);}
        var input=new CreditOrderInput(V(s.Quote,"id"),V(s.Quote,"fingerprint"),"Synthetic upfront QA","09100000000",zero?null:new("IR","تهران","تهران","Synthetic QA only; no actual delivery","1234567890"),"No actual funds or person",true,true);var order=(await CreditOrderQa.Read(await s.Customer.PostAsJsonAsync("/api/credit-orders/commands/"+Id(),input)))["order"]!;var path="/api/admin/credit/orders/"+s.Owner+"/"+V(order["summary"]!,"id")+"/schedule";var anchor=DateOnly.FromDateTime(TimeZoneInfo.ConvertTime(DateTimeOffset.UtcNow,TimeZoneInfo.FindSystemTimeZoneById("Asia/Tehran")).DateTime).ToString("yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture);var previewInput=new CreditSchedulePreviewInput(V(order["summary"]!,"version"),null,"Persian",anchor);var preview=await CreditScheduleQa.Read(await finance.PostAsJsonAsync(path+"/preview",previewInput));var schedule=await CreditScheduleQa.Read(await finance.PostAsJsonAsync(path+"/commands/"+Id(),new SaveCreditScheduleInput(previewInput.OrderVersion,null,"Persian",anchor,V(preview,"fingerprint"),true)));return new(s.Customer,s.Owner,order,schedule["revision"]!,s.Goods.Variant);
    }
    private static CreditUpfrontInput Input(Scenario s,string action="ConfirmReceipt",string? version=null,bool closed=false)=>new(action,V(s.Order["summary"]!,"version"),V(s.Schedule,"version"),version,action=="ConfirmReceipt"?"SYNTHETIC-FULL-UPFRONT-REFERENCE":"","Synthetic private manual confirmation 🎮",DateTimeOffset.UtcNow,true,closed);
    private static string EventVersion(JsonNode r)=>V(r["event"]!["summary"]!,"version");
    private static async Task<JsonNode> Write(HttpClient client,Scenario s,CreditUpfrontInput input,string? command=null)=>await ReadUpfront(await client.PostAsJsonAsync(Base(s)+"/commands/"+(command??Id()),input));
    [Fact]public async Task PositiveReceiptIsPrivateCannotPayOrFulfillAndDateAmendmentDoesNotCreateMoney()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(finance,reviewer);using var customer=s.Customer;var page=await ReadUpfront(await finance.GetAsync(Base(s)));Assert.True(page["canConfirmReceipt"]!.GetValue<bool>());Assert.Equal(V(s.Schedule["calculation"]!,"upfrontTotalRial"),V(page,"requiredAmountRial"));var first=await Write(finance,s,Input(s));Assert.Equal("ReceiptConfirmed",V(first["event"]!["summary"]!,"state"));Assert.Equal(V(page,"requiredAmountRial"),V(first["event"]!["summary"]!,"acknowledgedAmountRial"));Assert.False(first["canPay"]!.GetValue<bool>());Assert.False(first["canFulfill"]!.GetValue<bool>());Assert.False(first["bankVerified"]!.GetValue<bool>());
        var own=await ReadUpfront(await customer.GetAsync(Own(s)));foreach(var secret in new[]{"SYNTHETIC-FULL-UPFRONT-REFERENCE","Synthetic private manual confirmation","reference","note","actorId"})Assert.DoesNotContain(secret,own.ToJsonString(),StringComparison.OrdinalIgnoreCase);
        var date=DateOnly.Parse(V(s.Schedule["calculation"]!,"anchorDate")).AddDays(1).ToString("yyyy-MM-dd");var p=await CreditScheduleQa.Read(await finance.PostAsJsonAsync(Schedule(s)+"/preview",new CreditSchedulePreviewInput(V(s.Order["summary"]!,"version"),V(s.Schedule,"version"),"Gregorian",date)));var amended=await CreditScheduleQa.Read(await finance.PostAsJsonAsync(Schedule(s)+"/commands/"+Id(),new SaveCreditScheduleInput(V(s.Order["summary"]!,"version"),V(s.Schedule,"version"),"Gregorian",date,V(p,"fingerprint"),true)));s=s with{Schedule=amended["revision"]!};page=await ReadUpfront(await finance.GetAsync(Base(s)));Assert.Equal("ReceiptConfirmed",V(page["current"]!,"state"));Assert.False(page["canConfirmReceipt"]!.GetValue<bool>());var revoked=await Write(finance,s,Input(s,"RevokeConfirmation",EventVersion(first)));var again=await Write(finance,s,Input(s,version:EventVersion(revoked)));Assert.Equal(3,again["event"]!["summary"]!["sequence"]!.GetValue<int>());var history=await ReadUpfront(await finance.GetAsync(Base(s)+"/history"));Assert.Equal(3,history["items"]!.AsArray().Count);
        await using var scope=sql.Factory.Services.CreateAsyncScope();Assert.Equal(OrderState.AwaitingPayment,(await scope.ServiceProvider.GetRequiredService<SalesDbContext>().Orders.SingleAsync(x=>x.Id==OrderId(s))).State);Assert.Equal(1,(await scope.ServiceProvider.GetRequiredService<InventoryDbContext>().Stock.SingleAsync(x=>x.VariantId==s.Variant)).Reserved);var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();Assert.Single(await db.UpfrontConfirmations.Where(x=>x.OrderId==OrderId(s)).ToArrayAsync());Assert.DoesNotContain("SYNTHETIC",System.Text.Encoding.UTF8.GetString((await db.UpfrontEvents.FirstAsync()).ProtectedEvent));
    }
    [Fact]public async Task AuditRollbackReplayAndCompetingConfirmationsAreAtomic()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(finance,reviewer);using var customer=s.Customer;var cmd=Id();var path=Base(s)+"/commands/"+cmd;var input=Input(s);
        await using(var scope=sql.Factory.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_QA_UpfrontAudit CHECK ([Action]<>'CREDIT_UPFRONT_CONFIRMRECEIPT')");try{using var failed=await finance.PostAsJsonAsync(path,input);Assert.Equal(HttpStatusCode.Conflict,failed.StatusCode);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_QA_UpfrontAudit");}
        await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();Assert.False(await db.UpfrontConfirmations.AnyAsync());Assert.False(await db.UpfrontEvents.AnyAsync());Assert.False(await db.UpfrontCommands.AnyAsync());}
        var both=await Task.WhenAll(finance.PostAsJsonAsync(path,input),finance.PostAsJsonAsync(path,input));var results=await Task.WhenAll(both.Select(ReadUpfront));Assert.Single(results,x=>x["replayed"]!.GetValue<bool>());Assert.Equal(EventVersion(results[0]),EventVersion(results[1]));using(var conflict=await finance.PostAsJsonAsync(path,input with{Note="Different intent"}))Assert.Equal(HttpStatusCode.Conflict,conflict.StatusCode);var revoke=Input(s,"RevokeConfirmation",EventVersion(results[0]));var race=await Task.WhenAll(finance.PostAsJsonAsync(Base(s)+"/commands/"+Id(),revoke),finance.PostAsJsonAsync(Base(s)+"/commands/"+Id(),revoke));Assert.Single(race,x=>x.StatusCode==HttpStatusCode.OK);Assert.Single(race,x=>x.StatusCode==HttpStatusCode.Conflict);foreach(var r in race)if(r.IsSuccessStatusCode)await ReadUpfront(r);else r.Dispose();var receipt=await ReadUpfront(await finance.GetAsync(path));Assert.True(receipt["replayed"]!.GetValue<bool>());await using var final=sql.Factory.Services.CreateAsyncScope();Assert.Equal(2,await final.ServiceProvider.GetRequiredService<CreditDbContext>().UpfrontEvents.CountAsync());Assert.Equal(1,await final.ServiceProvider.GetRequiredService<IdentityContext>().Audit.CountAsync(x=>x.Resource==path));
    }
    [Fact]public async Task CancellationRacesNeverAllocateAndClosedCorrectionsRequireAcknowledgement()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(finance,reviewer);using var customer=s.Customer;var first=await Write(finance,s,Input(s));await CreditOrderQa.Read(await customer.PostAsJsonAsync("/api/orders/v2/"+OrderId(s)+"/cancel",new{version=V(s.Order["summary"]!,"version")}));var page=await ReadUpfront(await finance.GetAsync(Base(s)));s=s with{Order=s.Order.DeepClone()};s.Order["summary"]!["version"]=V(page,"orderVersion");using(var absentAck=await finance.PostAsJsonAsync(Base(s)+"/commands/"+Id(),Input(s,"RevokeConfirmation",EventVersion(first))))Assert.Equal(HttpStatusCode.Conflict,absentAck.StatusCode);var revoked=await Write(finance,s,Input(s,"RevokeConfirmation",EventVersion(first),true));using(var noRevival=await finance.PostAsJsonAsync(Base(s)+"/commands/"+Id(),Input(s,version:EventVersion(revoked))))Assert.Equal(HttpStatusCode.Conflict,noRevival.StatusCode);
        var other=await Ready(finance,reviewer);using var otherCustomer=other.Customer;var attempts=await Task.WhenAll(otherCustomer.PostAsJsonAsync("/api/orders/v2/"+OrderId(other)+"/cancel",new{version=V(other.Order["summary"]!,"version")}),finance.PostAsJsonAsync(Base(other)+"/commands/"+Id(),Input(other)));Assert.Equal(HttpStatusCode.OK,attempts[0].StatusCode);Assert.Contains(attempts[1].StatusCode,new[]{HttpStatusCode.OK,HttpStatusCode.Conflict});foreach(var r in attempts)r.Dispose();await using var scope=sql.Factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<SalesDbContext>();Assert.Equal(OrderState.Cancelled,(await db.Orders.SingleAsync(x=>x.Id==OrderId(other))).State);Assert.Equal(0,(await scope.ServiceProvider.GetRequiredService<InventoryDbContext>().Stock.SingleAsync(x=>x.VariantId==other.Variant)).Reserved);Assert.True(await scope.ServiceProvider.GetRequiredService<CreditDbContext>().PurchaseScopeUses.AnyAsync(x=>x.OrderId==OrderId(other)));
    }
    [Fact]public async Task AuthorizationForgedMoneyTamperingForeignKeysAndGuardedDownFailClosed()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");using var sales=await Staff("SalesManager");var s=await Ready(finance,reviewer);using var customer=s.Customer;foreach(var denied in new[]{reviewer,sales,customer}){using var r=await denied.GetAsync(Base(s));Assert.Equal(HttpStatusCode.Forbidden,r.StatusCode);}var other=await Customer();using(var stranger=other.Client){using var r=await stranger.GetAsync(Own(s));Assert.Equal(HttpStatusCode.NotFound,r.StatusCode);}var forged=JsonSerializer.SerializeToNode(Input(s),new JsonSerializerOptions(JsonSerializerDefaults.Web))!.AsObject();forged["amountRial"]="1";using(var bad=await finance.PostAsJsonAsync(Base(s)+"/commands/"+Id(),forged))Assert.Equal(HttpStatusCode.BadRequest,bad.StatusCode);using(var bad=await finance.GetAsync(Base(s)+"/history?beforeSequence=01"))Assert.Equal(HttpStatusCode.BadRequest,bad.StatusCode);
        var cmd=Id();var first=await Write(finance,s,Input(s),cmd);using(var wrongActor=await reviewer.GetAsync(Base(s)+"/commands/"+cmd))Assert.Equal(HttpStatusCode.Forbidden,wrongActor.StatusCode);var otherOrder=await Ready(finance,reviewer);using var customer2=otherOrder.Customer;var second=await Write(finance,otherOrder,Input(otherOrder));await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var row=await db.UpfrontConfirmations.SingleAsync(x=>x.OrderId==OrderId(s));row.RequiredAmountRial++;Assert.Equal("credit_upfront_history_immutable",(await Assert.ThrowsAsync<BusinessException>(()=>db.SaveChangesAsync())).Code);db.ChangeTracker.Clear();var id=V(first["event"]!["summary"]!,"id");await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[UpfrontEvents] SET [ConfirmationId]={V(second["event"]!["summary"]!,"confirmationId")} WHERE [Id]={id}"));await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>db.GetService<IMigrator>().MigrateAsync("20261027151329_ChequeLedger"));await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[UpfrontEvents] SET [ProtectedEvent]={new byte[]{1,2,3}} WHERE [Id]={id}");}
        using(var broken=await finance.GetAsync(Base(s)))Assert.Equal(HttpStatusCode.ServiceUnavailable,broken.StatusCode);await using(var scope=sql.Factory.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<CreditDbContext>().Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[UpfrontCommands] SET [ResultHash]={new string('0',64)} WHERE [CommandId]={cmd}");using(var broken=await finance.GetAsync(Base(s)+"/commands/"+cmd))Assert.Equal(HttpStatusCode.ServiceUnavailable,broken.StatusCode);finance.DefaultRequestHeaders.Remove("Origin");finance.DefaultRequestHeaders.Add("Origin","https://untrusted.example");using(var bad=await finance.PostAsJsonAsync(Base(otherOrder)+"/commands/"+Id(),Input(otherOrder,"RevokeConfirmation",EventVersion(second))))Assert.Equal(HttpStatusCode.Forbidden,bad.StatusCode);
    }
    [Fact]public async Task ZeroUpfrontForDigitalItemUsesExplicitNoFundsDueWithoutInventingReceipt()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(finance,reviewer,true);using var customer=s.Customer;var page=await ReadUpfront(await finance.GetAsync(Base(s)));Assert.Equal("0",V(page,"requiredAmountRial"));Assert.False(page["canConfirmReceipt"]!.GetValue<bool>());Assert.True(page["canConfirmNoUpfrontDue"]!.GetValue<bool>());using(var wrong=await finance.PostAsJsonAsync(Base(s)+"/commands/"+Id(),Input(s)))Assert.Equal(HttpStatusCode.Conflict,wrong.StatusCode);var first=await Write(finance,s,Input(s,"ConfirmNoUpfrontDue"));Assert.Equal("NoUpfrontDue",V(first["event"]!["summary"]!,"state"));Assert.Equal("0",V(first["event"]!["summary"]!,"acknowledgedAmountRial"));Assert.Equal("",V(first["event"]!,"reference"));Assert.False(first["bankVerified"]!.GetValue<bool>());Assert.False(first["canFulfill"]!.GetValue<bool>());
    }
    private sealed class FutureClock(DateTimeOffset at):TimeProvider{public override DateTimeOffset GetUtcNow()=>at;}
    [Fact]public async Task ExpiryDeniesFreshConfirmationWhileHistoricalReceiptRemainsRecoverable()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(finance,reviewer);using var customer=s.Customer;var cmd=Id();var input=Input(s);var first=await Write(finance,s,input,cmd);using var future=sql.Factory.WithWebHostBuilder(b=>b.ConfigureTestServices(services=>services.AddSingleton<TimeProvider>(new FutureClock(DateTimeOffset.Parse(V(s.Order["summary"]!,"expiresAt")).AddHours(1)))));using var later=future.CreateClient(new(){HandleCookies=false});foreach(var h in finance.DefaultRequestHeaders)later.DefaultRequestHeaders.TryAddWithoutValidation(h.Key,h.Value);var replay=await ReadUpfront(await later.PostAsJsonAsync(Base(s)+"/commands/"+cmd,input));Assert.True(replay["replayed"]!.GetValue<bool>());Assert.Equal(first["event"]!.ToJsonString(),replay["event"]!.ToJsonString());var page=await ReadUpfront(await later.GetAsync(Base(s)));Assert.False(page["canConfirmReceipt"]!.GetValue<bool>());using(var closed=await later.PostAsJsonAsync(Base(s)+"/commands/"+Id(),input))Assert.Equal(HttpStatusCode.Conflict,closed.StatusCode);await using var scope=sql.Factory.Services.CreateAsyncScope();Assert.Single(await scope.ServiceProvider.GetRequiredService<CreditDbContext>().UpfrontEvents.ToArrayAsync());Assert.True(await scope.ServiceProvider.GetRequiredService<CreditDbContext>().PurchaseScopeUses.AnyAsync(x=>x.OrderId==OrderId(s)));
    }
}
